import { lazy, Suspense } from 'react'
import { Routes, Route, Navigate } from 'react-router-dom'
import { AuthGuard } from '@/app/guards/AuthGuard'
import { PublicGuard } from '@/app/guards/PublicGuard'
import { AdminGuard } from '@/app/guards/AdminGuard'
import { SuperAdminGuard } from '@/app/guards/SuperAdminGuard'
import { TenantAccessGuard } from '@/app/guards/TenantAccessGuard'

// Layouts kept eager so the shell paints immediately
import { AuthLayout } from '@/features/auth/AuthLayout'
import { AppShell } from '@/features/shell/AppShell'

// Helper: turn a named export into a default export for React.lazy
const lazyNamed = <T extends Record<string, any>, K extends keyof T>(
  loader: () => Promise<T>,
  name: K,
) => lazy(() => loader().then((m) => ({ default: m[name] })))

// Auth pages
const LoginPage = lazyNamed(() => import('@/features/auth/LoginPage'), 'LoginPage')
const SignupPage = lazyNamed(() => import('@/features/auth/SignupPage'), 'SignupPage')
const ForgotPasswordPage = lazyNamed(() => import('@/features/auth/ForgotPasswordPage'), 'ForgotPasswordPage')
const ResetPasswordPage = lazyNamed(() => import('@/features/auth/ResetPasswordPage'), 'ResetPasswordPage')
const AcceptInvitePage = lazyNamed(() => import('@/features/auth/AcceptInvitePage'), 'AcceptInvitePage')

// App pages
const HomePage = lazyNamed(() => import('@/features/home/HomePage'), 'HomePage')
const ProjectsPage = lazyNamed(() => import('@/features/projects/ProjectsPage'), 'ProjectsPage')
const WorkplacesPage = lazyNamed(() => import('@/features/workplaces/WorkplacesPage'), 'WorkplacesPage')
const WalletPage = lazyNamed(() => import('@/features/wallet/WalletPage'), 'WalletPage')
const CommunityPage = lazyNamed(() => import('@/features/community/CommunityPage'), 'CommunityPage')
const NetworkPage = lazyNamed(() => import('@/features/network/NetworkPage'), 'NetworkPage')
const PortfolioPage = lazyNamed(() => import('@/features/portfolio/PortfolioPage'), 'PortfolioPage')
const ProjectLayout = lazyNamed(() => import('@/features/project/ProjectLayout'), 'ProjectLayout')
const ProjectOverviewPage = lazyNamed(() => import('@/features/project/ProjectOverviewPage'), 'ProjectOverviewPage')
const ProjectOrganiserPage = lazyNamed(() => import('@/features/project/ProjectOrganiserPage'), 'ProjectOrganiserPage')
const ProjectDashboardPage = lazyNamed(() => import('@/features/project/ProjectDashboardPage'), 'ProjectDashboardPage')
const ProjectSettingsPage = lazyNamed(() => import('@/features/project/ProjectSettingsPage'), 'ProjectSettingsPage')
const ObjectiveWorkspacePage = lazyNamed(() => import('@/features/objectives/ObjectiveWorkspacePage'), 'ObjectiveWorkspacePage')
const NavigatorPage = lazyNamed(() => import('@/features/navigator/NavigatorPage'), 'NavigatorPage')
const GoalsPage = lazyNamed(() => import('@/features/goals/GoalsPage'), 'GoalsPage')
const GoalDetailPage = lazyNamed(() => import('@/features/goals/GoalDetailPage'), 'GoalDetailPage')
const RewardsPage = lazyNamed(() => import('@/features/rewards/RewardsPage'), 'RewardsPage')
const ProfileLayout = lazyNamed(() => import('@/features/profile/ProfileLayout'), 'ProfileLayout')
const ProfileOverviewPage = lazyNamed(() => import('@/features/profile/ProfileOverviewPage'), 'ProfileOverviewPage')
const ProfileAppearancePage = lazyNamed(() => import('@/features/profile/ProfileAppearancePage'), 'ProfileAppearancePage')
const ProfileLanguagePage = lazyNamed(() => import('@/features/profile/ProfileLanguagePage'), 'ProfileLanguagePage')
const NotificationsPage = lazyNamed(() => import('@/features/notifications/NotificationsPage'), 'NotificationsPage')
const SearchPage = lazyNamed(() => import('@/features/search/SearchPage'), 'SearchPage')

// Marketplace
const MarketplaceLayout = lazyNamed(() => import('@/features/marketplace/MarketplaceLayout'), 'MarketplaceLayout')
const AppsMarketplacePage = lazyNamed(() => import('@/features/marketplace/AppsMarketplacePage'), 'AppsMarketplacePage')
const TemplatesMarketplacePage = lazyNamed(() => import('@/features/marketplace/TemplatesMarketplacePage'), 'TemplatesMarketplacePage')
const SecondaryMarketPage = lazyNamed(() => import('@/features/marketplace/SecondaryMarketPage'), 'SecondaryMarketPage')
const FundsMarketplacePage = lazyNamed(() => import('@/features/marketplace/FundsMarketplacePage'), 'FundsMarketplacePage')
const DeveloperPage = lazyNamed(() => import('@/features/marketplace/DeveloperPage'), 'DeveloperPage')

// Admin
const AdminLayout = lazyNamed(() => import('@/features/admin/AdminLayout'), 'AdminLayout')
const TenantOverviewPage = lazyNamed(() => import('@/features/admin/TenantOverviewPage'), 'TenantOverviewPage')
const BrandingPage = lazyNamed(() => import('@/features/admin/BrandingPage'), 'BrandingPage')
const MembersPage = lazyNamed(() => import('@/features/admin/MembersPage'), 'MembersPage')
const LocalizationPage = lazyNamed(() => import('@/features/admin/LocalizationPage'), 'LocalizationPage')
const AppsAdminPage = lazyNamed(() => import('@/features/admin/AppsAdminPage'), 'AppsAdminPage')
const TemplatesAdminPage = lazyNamed(() => import('@/features/admin/TemplatesAdminPage'), 'TemplatesAdminPage')
const CreditsAdminPage = lazyNamed(() => import('@/features/admin/CreditsAdminPage'), 'CreditsAdminPage')
const NotificationsAdminPage = lazyNamed(() => import('@/features/admin/NotificationsAdminPage'), 'NotificationsAdminPage')
const EmailTemplatesPage = lazyNamed(() => import('@/features/admin/EmailTemplatesPage'), 'EmailTemplatesPage')
const LegalPage = lazyNamed(() => import('@/features/admin/LegalPage'), 'LegalPage')
const AnalyticsPage = lazyNamed(() => import('@/features/admin/AnalyticsPage'), 'AnalyticsPage')
const AuditLogPage = lazyNamed(() => import('@/features/admin/AuditLogPage'), 'AuditLogPage')
const TenantsAdminPage = lazyNamed(() => import('@/features/admin/TenantsAdminPage'), 'TenantsAdminPage')

// Settings
const SettingsLayout = lazyNamed(() => import('@/features/settings/SettingsLayout'), 'SettingsLayout')
const AccountPage = lazyNamed(() => import('@/features/settings/AccountPage'), 'AccountPage')
const AppearancePage = lazyNamed(() => import('@/features/settings/AppearancePage'), 'AppearancePage')
const LanguagePage = lazyNamed(() => import('@/features/settings/LanguagePage'), 'LanguagePage')
const NotificationSettingsPage = lazyNamed(() => import('@/features/settings/NotificationSettingsPage'), 'NotificationSettingsPage')
const SecurityPage = lazyNamed(() => import('@/features/settings/SecurityPage'), 'SecurityPage')
const SkillsPage = lazyNamed(() => import('@/features/settings/SkillsPage'), 'SkillsPage')

function RouteFallback() {
  return (
    <div className="flex items-center justify-center h-full w-full p-12">
      <div className="animate-spin rounded-full h-6 w-6 border-2 border-accent border-t-transparent" />
    </div>
  )
}

export function AppRoutes() {
  return (
    <Suspense fallback={<RouteFallback />}>
      <Routes>
        {/* Root + /home redirect */}
        <Route path="/" element={<Navigate to="/app/home" replace />} />
        <Route path="/home" element={<Navigate to="/app/home" replace />} />

        {/* Auth routes */}
        <Route element={<PublicGuard />}>
          <Route element={<AuthLayout />}>
            <Route path="/auth/login" element={<LoginPage />} />
            <Route path="/auth/signup" element={<SignupPage />} />
            <Route path="/auth/forgot-password" element={<ForgotPasswordPage />} />
            <Route path="/auth/reset-password" element={<ResetPasswordPage />} />
            <Route path="/auth/accept-invite" element={<AcceptInvitePage />} />
          </Route>
        </Route>

        {/* Protected app routes */}
        <Route element={<AuthGuard />}>
          <Route element={<TenantAccessGuard />}>
            <Route element={<AppShell />}>
              <Route path="/app/home" element={<HomePage />} />
              <Route path="/app/workplaces" element={<WorkplacesPage />} />
              <Route path="/app/projects" element={<ProjectsPage />} />

              <Route path="/app/project/:projectId" element={<ProjectLayout />}>
                <Route index element={<ProjectOverviewPage />} />
                <Route path="overview" element={<ProjectOverviewPage />} />
                <Route path="organiser" element={<ProjectOrganiserPage />} />
                <Route path="navigator" element={<NavigatorPage />} />
                <Route path="goals" element={<GoalsPage />} />
                <Route path="goals/:goalId" element={<GoalDetailPage />} />
                <Route path="dashboard" element={<ProjectDashboardPage />} />
                <Route path="rewards" element={<RewardsPage />} />
                <Route path="settings" element={<ProjectSettingsPage />} />
              </Route>

              <Route path="/app/objective/:objectiveId" element={<ObjectiveWorkspacePage />} />

              <Route path="/app/wallet" element={<WalletPage />} />
              <Route path="/app/community" element={<CommunityPage />} />
              <Route path="/app/network" element={<NetworkPage />} />
              <Route path="/app/portfolio" element={<PortfolioPage />} />
              <Route path="/app/inbox" element={<NotificationsPage />} />
              <Route path="/app/search" element={<SearchPage />} />
              <Route path="/app/profile" element={<ProfileLayout />}>
                <Route index element={<Navigate to="overview" replace />} />
                <Route path="overview" element={<ProfileOverviewPage />} />
                <Route path="appearance" element={<ProfileAppearancePage />} />
                <Route path="language" element={<ProfileLanguagePage />} />
              </Route>

              {/* Marketplace */}
              <Route path="/marketplace" element={<MarketplaceLayout />}>
                <Route index element={<Navigate to="apps" replace />} />
                <Route path="apps" element={<AppsMarketplacePage />} />
                <Route path="templates" element={<TemplatesMarketplacePage />} />
                <Route path="funds" element={<FundsMarketplacePage />} />
                <Route path="secondary" element={<SecondaryMarketPage />} />
                <Route path="developer" element={<DeveloperPage />} />
              </Route>

              {/* Settings */}
              <Route path="/settings" element={<SettingsLayout />}>
                <Route index element={<Navigate to="account" replace />} />
                <Route path="account" element={<AccountPage />} />
                <Route path="appearance" element={<AppearancePage />} />
                <Route path="language" element={<LanguagePage />} />
                <Route path="notifications" element={<NotificationSettingsPage />} />
                <Route path="security" element={<SecurityPage />} />
                <Route path="skills" element={<SkillsPage />} />
              </Route>

              {/* Admin */}
              <Route element={<AdminGuard />}>
                <Route path="/admin" element={<AdminLayout />}>
                  <Route index element={<Navigate to="tenant" replace />} />
                  <Route path="tenant" element={<TenantOverviewPage />} />
                  <Route path="branding" element={<BrandingPage />} />
                  <Route path="localization" element={<LocalizationPage />} />
                  <Route path="apps" element={<AppsAdminPage />} />
                  <Route path="templates" element={<TemplatesAdminPage />} />
                  <Route path="members" element={<MembersPage />} />
                  <Route path="credits" element={<CreditsAdminPage />} />
                  <Route path="notifications" element={<NotificationsAdminPage />} />
                  <Route path="email-templates" element={<EmailTemplatesPage />} />
                  <Route path="legal" element={<LegalPage />} />
                  <Route path="analytics" element={<AnalyticsPage />} />
                  <Route path="audit" element={<AuditLogPage />} />
                  <Route element={<SuperAdminGuard />}>
                    <Route path="tenants" element={<TenantsAdminPage />} />
                  </Route>
                </Route>
              </Route>
            </Route>
          </Route>
        </Route>

        <Route path="*" element={<Navigate to="/app/home" replace />} />
      </Routes>
    </Suspense>
  )
}
